<script setup lang="ts">
import {computed,ref} from 'vue'
import {NButton,NInput,NModal,NSelect} from 'naive-ui'
import {api,money,statuses,type Transfer,type Account} from '../api/funds'
const props=defineProps<{items:Transfer[];accounts:Account[];approvals:boolean;trusted:boolean}>()
const emit=defineEmits<{changed:[];notice:[string];}>()
const tag=ref<string|null>(null)
const tags=computed(()=>[...new Set(props.items.flatMap(t=>t.tags))].map(value=>({label:value,value})))
const items=computed(()=>props.items.filter(t=>(!props.approvals||t.status==='pending')&&(!tag.value||t.tags.includes(tag.value))))
const detail=ref<Transfer|null>(null),error=ref(''),reason=ref(''),busy=ref(false)
async function open(item:Transfer){error.value='';reason.value='';try{detail.value=await api.detail(item.id)}catch(e){error.value=(e as Error).message}}
async function decide(approve:boolean){if(!detail.value||busy.value)return;if(!approve&&!reason.value.trim()){error.value='请填写拒绝原因';return}busy.value=true;error.value='';try{detail.value=await api.decide(detail.value,approve,reason.value);emit('changed');emit('notice',approve?'审批已过账':'已拒绝')}catch(e){error.value=(e as Error).message;detail.value=await api.detail(detail.value.id).catch(()=>detail.value)}finally{busy.value=false}}
async function reverse(){if(busy.value)return;if(!detail.value||!reason.value.trim()){error.value='请填写冲销原因';return}busy.value=true;error.value='';try{const result=await api.reverse(detail.value.id,reason.value);emit('notice','冲销流水'+(statuses[result.status]||result.status));detail.value=await api.detail(detail.value.id);emit('changed')}catch(e){error.value=(e as Error).message+'。请查看流水记录后再决定是否重新提交。'}finally{busy.value=false}}
</script>
<template><h2>{{approvals?'待审批':'划转记录'}}</h2><NSelect v-model:value="tag" clearable placeholder="所有标签" :options="tags"/><p v-if="!items.length" class="muted">暂无{{approvals?'待审批事项':'划转记录'}}。</p><p v-if="error&&!detail" class="error">{{error}}</p><div v-if="items.length" class="table-wrap"><table><thead><tr><th>日期</th><th>来源 → 去向</th><th>金额（元）</th><th>状态</th><th>发起人</th><th>审批依据</th><th></th></tr></thead><tbody><tr v-for="t in items" :key="t.id"><td>{{t.effective_date}}<small>{{t.tags.join("，")}}</small></td><td>{{t.source_account_name}} → {{t.destination_account_name}}</td><td>{{money(t.amount_minor)}}</td><td>{{statuses[t.status]}}</td><td>{{t.actor_name}}</td><td>{{t.approval_mode==='automatic'?'受信任身份自动过账':t.approval_mode==='manual'?'人工审批':'待处理'}} {{t.approved_by_name||''}}</td><td><NButton size="small" @click="open(t)">详情</NButton></td></tr></tbody></table></div><NModal :show="!!detail" preset="card" title="流水详情" class="dialog" @close="detail=null"><template v-if="detail"><p><strong>{{detail.source_account_name}} → {{detail.destination_account_name}}</strong> ¥{{money(detail.amount_minor)}}，{{statuses[detail.status]}}</p><dl><dt>编号 / 版本</dt><dd>{{detail.id}} / {{detail.version}}</dd><dt>业务日期</dt><dd>{{detail.effective_date}}</dd><dt>说明 / 往来方</dt><dd>{{detail.description||'—'}} / {{detail.counterparty||'—'}}</dd><dt>发起 / 审批</dt><dd>{{detail.actor_name}} / {{detail.approved_by_name||'—'}}（{{detail.approval_mode||'待处理'}}）</dd><dt>冲销原流水</dt><dd>{{detail.reversal_of||'—'}}</dd><dt>原因</dt><dd>{{detail.reason||'—'}}</dd></dl><h3>记账分录</h3><p v-if="!detail.journal_lines?.length">尚未产生分录。</p><table v-else><thead><tr><th>对象</th><th>借方</th><th>贷方</th></tr></thead><tbody><tr v-for="(line,index) in detail.journal_lines" :key="index"><td>{{accounts.find(a=>a.id===line.account_id)?.name||line.account_id}}</td><td>{{money(line.debit_minor)}}</td><td>{{money(line.credit_minor)}}</td></tr></tbody></table><h3>审计记录</h3><pre>{{JSON.stringify(detail.audit,null,2)}}</pre><template v-if="(detail.status==='pending'&&trusted)||detail.status==='posted'"><label>处理原因<NInput v-model:value="reason" :disabled="busy" placeholder="拒绝或冲销时必填"/></label><div class="actions"><template v-if="detail.status==='pending'&&trusted"><NButton :loading="busy" @click="decide(false)">拒绝</NButton><NButton type="primary" :loading="busy" @click="decide(true)">批准并过账</NButton></template><NButton v-if="detail.status==='posted'" :loading="busy" @click="reverse">申请冲销</NButton></div></template><p v-if="error" class="error">{{error}}</p></template></NModal></template>
